WITH eu AS (SELECT e.id AS executivo_id, COALESCE(e.cargo = 'Agente de prospecção', false) AS agente, lower(u.email) = (SELECT valor FROM configuracao WHERE chave = 'admin_email') AS admin FROM INT_USER u LEFT JOIN executivos e ON lower(e.email) = lower(u.email) AND e.ativo WHERE u.user_id = CAST(:VAR_USER AS UUID) AND u.enabled AND lower(u.email) LIKE '%@' || (SELECT valor FROM configuracao WHERE chave = 'dominio')) SELECT p.pedido_id, p.cliente, p.site, p.status, p.lote_id, l.nome AS lote, p.referencia_externa AS referencia, p.produtos, p.portal_url, p.banners_situacao, p.telufia, COALESCE(p.motivo_catalogo, p.erro) AS motivo, p.criado_em, p.concluido_em, CASE WHEN p.status = 'na_fila' THEN NULL ELSE GREATEST(0, EXTRACT(EPOCH FROM (CASE WHEN p.status = 'concluido' THEN COALESCE(p.concluido_em, now()) WHEN p.status IN ('falhou', 'precisa_catalogo') THEN COALESCE(p.falhou_em, p.atualizado_em, now()) ELSE now() END - COALESCE(p.saiu_fila_em, p.criado_em)))) END AS segundos, (p.status NOT IN ('na_fila', 'concluido', 'falhou', 'precisa_catalogo')) AS relogio_ativo, (p.execucao_atual IS NOT NULL) AS em_execucao, COALESCE(e.nome, 'não informado') AS usuario, av.nota AS avaliacao_nota, av.problemas AS avaliacao_problemas, av.comentario AS avaliacao_comentario FROM pedidos p JOIN eu ON (eu.admin OR eu.agente OR p.executivo_id = eu.executivo_id) LEFT JOIN lotes l ON l.id = p.lote_id LEFT JOIN executivos e ON e.id = p.executivo_id LEFT JOIN avaliacoes_portal av ON av.pedido_id = p.pedido_id WHERE p.automatico AND (:status IS NULL OR :status = '' OR p.status = :status OR (:status = 'falhou' AND p.status = 'precisa_catalogo') OR (:status = 'extraindo' AND p.status IN ('curadoria', 'aguardando_anexo'))) AND (:lote IS NULL OR :lote = '' OR p.lote_id = CAST(:lote AS INTEGER)) ORDER BY p.id DESC LIMIT CAST(:limite AS INTEGER) OFFSET CAST(:offset AS INTEGER)
